      { r: "c", es: ["Sí, pasa. Apoyá la SUBE ahí.", "Sí. Apoyá la tarjeta acá.", "Sí, te deja ahí. Apoyá la SUBE.", "Pasa, sí. Marcá la SUBE en la maquinita.", "Sí, sí. Apoyá la SUBE acá.", "Sí, pasa por ahí. Apoyá la tarjeta.", "Pasa, pasa. Apoyá la SUBE, dale.", "Sí, te deja en Plaza Italia. Apoyá la SUBE en la máquina.", "Sí. Marcá la tarjeta ahí, por favor.", "Sí, va para allá. Apoyá la SUBE."] },
      { you: "Ask the driver to let you know when you get there.", ok: [["avis"], ["dec", "baj"], ["dec", "lleg"], ["dec", "cuando"]], best: "¿Me avisás cuando lleguemos?", alts: ["¿Me avisás cuando estemos llegando?", "¿Me podés avisar cuando lleguemos a Plaza Italia?", "Dale, ¿me avisás dónde me tengo que bajar?", "¿Me avisás cuando sea mi parada?", "Gracias. ¿Me avisás cuando lleguemos?", "¿Me decís cuándo me tengo que bajar?", "Perdón, ¿me avisarías cuando lleguemos?", "¿Me avisás en Plaza Italia, por favor?", "Buenísimo. ¿Me podés avisar dónde bajo?", "¿Me decís cuando lleguemos, porfa?"], prep: ["b02"] },
      { r: "c", es: ["Uy, con este tránsito me voy a olvidar. Preguntale {s:a la señora|al señor}, que se baja ahí.", "Mirá, con todo este tráfico seguro me olvido. {s:La señora|El señor} se baja ahí, preguntale.", "Uf, no te prometo nada con este tránsito. Preguntale {s:a la señora|al señor} de acá, que se baja en Plaza Italia.", "Ay, me voy a olvidar, eh. Pero {s:la señora|el señor} se baja ahí, preguntale {s:a ella|a él}.", "Uh, no sé si me voy a acordar con tanto tránsito. Preguntale {s:a la señora|al señor}, que baja ahí.", "Mirá, yo me olvido seguro. {s:Esta señora|Este señor} se baja en Plaza Italia, preguntale.", "Con todo este tránsito me voy a olvidar, eh. Fijate con {s:la señora|el señor}, que baja ahí.", "Uf, te diría que sí, pero con este tránsito me olvido. Preguntale {s:a la señora|al señor}, que baja ahí.", "Uy, con tanto tráfico no te aseguro nada. {s:La señora|El señor} va a Plaza Italia, preguntale {s:a ella|a él}.", "Uh, mejor preguntale {s:a la señora|al señor}. Se baja ahí, y yo con este tránsito me olvido."] },
      { r: "s", es: ["Sí, yo me bajo en Plaza Italia. Te aviso, no te preocupes.", "Yo también voy a Plaza Italia. Quedate tranqui, yo te aviso.", "Ah, sí, me bajo ahí. Yo te aviso cuando lleguemos.", "Sí, sí, voy para ahí. No te hagas problema, te aviso.", "Sí, yo bajo ahí. Cuando lleguemos te aviso.", "Ah, voy para el mismo lado. No te preocupes, yo te digo.", "Sí, Plaza Italia es mi parada. Te aviso yo.", "Dale, yo también me bajo ahí. Te aviso, eh.", "Mirá, yo me bajo en Plaza Italia. Vos quedate cerca mío y te aviso.", "Sí, sí, yo te aviso. Me bajo justo ahí."] },
      { you: "Thank {s:the lady|the man}.", ok: ["gracias", "muy amable", "que amable"], best: "¡Muchas gracias!", alts: ["Mil gracias.", "Gracias, muy amable.", "¡Gracias, sos un sol!", "Ay, ¡qué amable! Gracias.", "Buenísimo, gracias.", "¡Gracias, me salvás!", "Dale, muchas gracias.", "¡Gracias, de verdad!", "Uy, muchísimas gracias.", "¡Qué amable! Te agradezco."], prep: ["b03"] },
      { r: "s", to: "c", es: ["Disculpe, ¿hoy desvía por la manifestación?", "¿Hoy sigue derecho por Santa Fe, o desvía?", "Perdone, ¿hoy hay desvío por la marcha?", "Disculpe, con la manifestación, ¿va por Santa Fe o se desvía?", "Perdón, ¿hoy hace el recorrido de siempre o desvía por la marcha?", "Una pregunta, ¿con la manifestación hoy cambia el recorrido?", "Disculpe, ¿sigue por Santa Fe hoy o hay desvío?", "Perdone, ¿por la marcha va a desviar?", "¿Y hoy va por Santa Fe, con la manifestación?", "Disculpe, ¿la manifestación le cambia el recorrido hoy?"], wait: 1800 },
      { r: "c", to: "s", es: ["Desvío por Córdoba, {s:señora|señor}. Faltan {paradas} paradas.", "Hoy voy por Córdoba. Son {paradas} paradas más.", "Sí, {s:señora|señor}, vamos por Córdoba. Quedan {paradas} paradas.", "Desviamos por Córdoba. De acá son {paradas} paradas.", "Hoy desviamos por Córdoba. Faltan {paradas} paradas.", "Vamos por Córdoba hoy. Quedan {paradas} paradas hasta Plaza Italia.", "Tomamos por Córdoba. A usted le faltan {paradas} paradas.", "Agarro por Córdoba, {s:señora|señor}. En {paradas} paradas llegamos.", "Hay desvío por Córdoba. Todavía faltan {paradas} paradas.", "Por Córdoba, {s:señora|señor}. Usted se baja en {paradas} paradas."] },
      { check: "paradas", q: { es: "¿Cuántas paradas faltan?", en: "How many stops to go?" } },
      { r: "s", es: ["Bueno, tenemos tiempo. ¿Vos vas a pasear?", "Ah, bueno, falta un ratito. ¿Y vos? ¿Vas a pasear?", "Tenemos un rato, entonces. ¿Vas a pasear por ahí?", "Bueno, hay tiempo. ¿Vos vas de paseo?", "Ah, hay un rato todavía. ¿Vos andás de paseo?", "Bueno, todavía falta. ¿Salís a pasear?", "Mirá, nos queda un ratito. ¿Vas de paseo por la zona?", "Ah, bueno, hay tiempo de charlar. ¿Vos salís a pasear hoy?", "Bueno, todavía hay tiempo. ¿Vas a dar una vuelta?", "Bueno, así que tenemos un rato. ¿Vas a pasear?"] },
      { pick: "plan", you: { amigos: "Say yes, you're going to meet a friend.", botanico: "Say yes, you're going for a walk in the Botanical Garden (el Jardín Botánico)." }, ok: { amigos: [["amig"]], botanico: [["botanico"], ["jardin bot"]] }, best: { amigos: "Sí, voy a encontrarme con una amiga.", botanico: "Sí, voy al Jardín Botánico." }, alts: { amigos: ["Sí, me voy a juntar con un amigo.", "Sí, voy a ver a una amiga.", "Sí, quedé con unos amigos.", "Sí, me encuentro con un amigo en la plaza.", "Sí, voy a tomar algo con una amiga.", "Sí, me junto con unos amigos.", "Sí, me espera un amigo allá.", "Sí, quedé en encontrarme con una amiga.", "Sí, voy a merendar con unos amigos.", "Sí, tengo planes con una amiga."], botanico: ["Sí, voy a pasear por el Jardín Botánico.", "Sí, al Botánico.", "Sí, quiero conocer el Botánico.", "Sí, me voy a dar una vuelta por el Botánico.", "Sí, voy a caminar un rato por el Jardín Botánico.", "Sí, voy a visitar el Jardín Botánico.", "Sí, me voy al Botánico.", "Sí, voy a recorrer el Jardín Botánico.", "Sí, tengo ganas de pasear por el Botánico.", "Sí, voy al Botánico a caminar un poco."] }, prep: [] },
      { pick: "plan", r: "s", es: { amigos: ["¡Ah, mirá qué lindo! Uy, ya llegamos. Nos bajamos en la próxima.", "¡Qué bueno! Uy, mirá, ya casi llegamos. La próxima es la nuestra.", "¡Ah, qué lindo! Bueno, ya estamos. Nos bajamos en la que viene.", "¡Mirá vos, qué bien! Uy, en la próxima nos bajamos.", "¡Qué lindo! Ah, mirá, ya estamos llegando. Bajamos en la próxima.", "¡Buenísimo! Che, ya llegamos, eh. La próxima bajamos.", "¡Qué bien, me alegro! Uy, ya estamos. Nos toca bajar en la próxima.", "¡Ah, bárbaro! Mirá, ya llegamos. Bajamos en la que viene.", "¡Qué lindo plan! Uy, se me pasó volando. Nos bajamos en la próxima.", "¡Ay, qué bueno! Bueno, ya casi llegamos. En la próxima nos bajamos."], botanico: ["¡Ah, el Botánico es hermoso! Uy, ya llegamos. Nos bajamos en la próxima.", "¡Qué bueno! Está divino el Botánico en esta época. Uy, mirá, ya casi llegamos. La próxima es la nuestra.", "¡Ah, te va a encantar! Bueno, ya estamos. Nos bajamos en la que viene.", "¡Mirá vos, qué lindo paseo! Uy, en la próxima nos bajamos.", "¡Ah, el Botánico es divino! Uy, mirá, ya estamos llegando. Bajamos en la próxima.", "¡Buenísimo, te va a gustar! Che, ya llegamos, eh. La próxima bajamos.", "¡Qué bien, el Botánico es precioso! Uy, ya estamos. Nos toca bajar en la próxima.", "¡Ah, bárbaro! Está muy lindo ahora. Mirá, ya llegamos. Bajamos en la que viene.", "¡Qué buen plan! Uy, se me pasó volando. Nos bajamos en la próxima.", "¡Ay, me encanta el Botánico! Bueno, ya casi llegamos. En la próxima nos bajamos."] }, wait: 2600 },
      { you: "There are people in the way. Say excuse me, you're getting off at the next one.", ok: [["permiso", "proxima"], ["baj", "proxima"], ["permiso", "baj"], ["perdon", "baj"], ["disculp", "baj"], ["permiso", "que viene"]], best: "Permiso, bajo en la próxima.", alts: ["Permiso, me bajo en la próxima.", "Perdón, ¿me das permiso? Bajo en la próxima.", "Con permiso, me bajo en la que viene.", "Permiso, permiso. Bajo en la próxima.", "Disculpá, me bajo en la próxima.", "Perdón, ¿me dejás pasar? Bajo en la próxima.", "Disculpen, bajo en la próxima.", "Permiso, ¿me hacés lugar? Bajo en la próxima.", "Perdón, permiso. Me bajo en la que viene.", "Permiso, ¿puedo pasar? Me bajo en la próxima."], prep: ["b04", "b05"] },
      { r: "s", es: ["Listo, llegamos. Plaza Italia está a dos cuadras, para allá. ¡Suerte!", "Bueno, acá es. Caminá dos cuadras para allá y estás en Plaza Italia. ¡Que te vaya bien!", "Ya está, llegamos. Plaza Italia queda a dos cuadras, para aquel lado. ¡Suerte!", "Acá bajamos. Son dos cuadras por allá hasta Plaza Italia. ¡Suerte, eh!", "Bueno, es acá. Plaza Italia te queda a dos cuadras, por allá. ¡Chau, suerte!", "Llegamos. Seguí dos cuadras derecho para allá y la ves a Plaza Italia. ¡Que te vaya lindo!", "Acá estamos. Dos cuadras para aquel lado y llegás a Plaza Italia. ¡Suerte!", "Listo, es acá. Plaza Italia está ahí nomás, a dos cuadras. ¡Que lo disfrutes!", "Bueno, bajamos acá. Para Plaza Italia son dos cuadras por allá. ¡Suerte, chau!", "Ya llegamos. Fijate, Plaza Italia está a dos cuadritas, para allá. ¡Que andes bien!"], wait: 1500 },
      { you: "Thank {s:the lady|the man} and say goodbye.", ok: ["gracias", "chau", "igualmente", "hasta luego", "nos vemos", "adios"], best: "¡Gracias por todo! Chau.", alts: ["Muchas gracias por la ayuda. ¡Chau!", "Mil gracias, ¡que tengas lindo día!", "¡Gracias! Chau, buen día.", "Gracias, igualmente. ¡Chau!", "Gracias por avisarme. ¡Hasta luego!", "¡Gracias! Que te vaya bien a vos también.", "Dale, gracias. ¡Nos vemos!", "Gracias, ¡sos muy amable! Chau.", "Gracias por darme una mano. ¡Chau!", "Mil gracias por todo. ¡Hasta luego!"], prep: ["b03"] }
