      { r: "j", es: ["Desde {hora} hasta el mediodía, más o menos.", "Cortan desde {hora}, hasta el mediodía.", "A partir de {hora} y hasta el mediodía.", "La cortan desde {hora}. Vuelve al mediodía, más o menos.", "Desde {hora}, y vuelve al mediodía.", "Me dijeron que desde {hora} hasta el mediodía.", "La cortan a {hora} y la vuelven a dar al mediodía, más o menos.", "Arrancan a {hora}. Hasta el mediodía no hay agua.", "A eso de {hora}. Y hasta el mediodía, calculo.", "Empiezan a {hora}, y para el mediodía ya tendría que volver."] },
      { check: "hora", q: { es: "¿Desde qué hora cortan el agua?", en: "What time does the water go off?" } },
      { r: "r", to: "j", es: ["{j:Julia|Julio}, ¿y el ascensor? Otra vez no anda.", "Che, {j:Julia|Julio}, el ascensor no funciona de nuevo.", "{j:Julia|Julio}, ¿viste que el ascensor se rompió otra vez?", "Ay, {j:Julia|Julio}, ¿qué pasa con el ascensor? Otra vez está parado.", "{j:Julia|Julio}, el ascensor otra vez no anda, ¿sabías?", "Ay, {j:Julia|Julio}, ¡de nuevo el ascensor! Está roto.", "Che, {j:Julia|Julio}, ¿qué onda el ascensor? Otra vez no funciona.", "Hola, {j:Julia|Julio}. Otra vez el ascensor no anda, ¿eh?", "¡{j:Julia|Julio}! ¿Viste el ascensor? Se trabó otra vez.", "Uf, {j:Julia|Julio}, el ascensor no anda de nuevo. ¿Lo pueden arreglar?"], wait: 1800 },
      { r: "j", to: "r", es: ["Ya llamé al técnico, {r:Rosa|Rodolfo}. Viene a la tarde.", "Sí, {r:Rosa|Rodolfo}, ya le avisé al técnico. Pasa esta tarde.", "Ya sé, {r:Rosa|Rodolfo}. El técnico viene a la tarde, ya lo llamé.", "Quedate tranqui, {r:Rosa|Rodolfo}, ya llamé al técnico y viene a la tarde.", "¡Uf, sí! Ya hablé con el técnico, {r:Rosa|Rodolfo}. Pasa a la tarde.", "Sí, ya sé, {r:Rosa|Rodolfo}. Hoy a la tarde lo vienen a arreglar.", "{r:Tranquila|Tranquilo}, {r:Rosa|Rodolfo}. Ya avisé y el técnico pasa a la tarde.", "Lo sé, {r:Rosa|Rodolfo}. A la tarde viene el técnico, ya hablé con él.", "Ya está todo hablado, {r:Rosa|Rodolfo}. Esta tarde pasa el técnico.", "Ya me ocupé, {r:Rosa|Rodolfo}. El técnico viene a la tarde."] },
      { r: "r", es: ["¡Hola! ¿Vos también subís por la escalera?", "Hola, ¿qué tal? ¿A vos también te toca la escalera?", "¡Hola! ¿Vos también vas a tener que subir a pie?", "Hola. ¿Así que vos también vas por la escalera?", "¡Hola! Che, ¿vos también a pie?", "Hola, ¿qué tal? Parece que hoy subimos todos por la escalera, ¿no?", "¡Buen día! ¿Y vos? ¿También subís caminando?", "Hola, ¿cómo andás? ¿También te toca escalera hoy?", "¡Hola! Qué embole, ¿no? ¿Vos también subís a pie?", "Hola. ¿Vos también estás sin ascensor?"] },
      { you: "Say yes, the elevator isn't working.", ok: [["no anda"], ["no funciona"], ["ascensor"], ["roto"], ["se rompio"], ["descompuesto"], ["escalera"], ["a pie"]], best: "Sí, el ascensor no anda.", alts: ["Sí, el ascensor no funciona.", "Y sí, no queda otra. El ascensor no anda.", "Sí, otra vez está roto el ascensor.", "Sí, ¡otra vez sin ascensor!", "Y sí, el ascensor se rompió de nuevo.", "Sí, por la escalera. El ascensor no anda.", "Sí, qué embole. No funciona el ascensor.", "Y sí, está descompuesto otra vez.", "Sí, sí, ¡otra vez no anda!", "Sí, subo a pie, el ascensor está roto."], prep: ["e04"] },
      { r: "r", es: ["¡Y con ese paquete! ¿Querés que te ayude?", "¡Uh, con ese paquete! ¿Te doy una mano?", "¿Y con semejante paquete? ¿Te ayudo a subirlo?", "Ay, ese paquete parece pesado. ¿Querés una mano?", "¡Y encima cargando eso! ¿Te ayudo?", "¿Y vas a subir todo eso? ¿Querés que te dé una mano?", "Ay, ¿con semejante caja? ¿Te ayudo a llevarla?", "Che, ese paquete se ve pesado. ¿Querés que te ayude a subirlo?", "¡Pobre, con ese paquete! ¿Te echo una mano?", "Mirá el paquete que tenés. ¿Necesitás ayuda?"] },
      { pick: "ayuda", you: { rechazar: "Say no thanks, it's fine.", aceptar: "Say yes, accept the help and thank {r:her|him}." }, ok: { rechazar: ["no gracias", "gracias no", "no te preocupes", "no hace falta", "no esta bien", "esta bien gracias", "no tranqui", "no todo bien", "gracias pero", "lo subo yo", "puedo yo", "no te hagas problema"], aceptar: ["si", "dale", "bueno", "de una", "por favor", ["agradec"], ["me ayud"], ["una mano"], "seria genial"] }, best: { rechazar: "No, gracias, está bien.", aceptar: "¡Sí, dale! Muchas gracias." }, alts: { rechazar: ["No te preocupes, gracias.", "Gracias, pero no hace falta.", "No, está bien, lo subo yo. ¡Gracias!", "No, tranqui, puedo. ¡Gracias!", "No, todo bien, gracias.", "No te hagas problema, puedo yo.", "No, no hace falta. Gracias igual.", "Gracias, pero no pesa tanto.", "No, tranqui, ¡gracias igual!", "Está bien, gracias. Puedo yo."], aceptar: ["Sí, por favor. ¡Gracias!", "Bueno, dale, te agradezco.", "¡Ay, sí, gracias! Pesa bastante.", "Sí, ¿me das una mano? Gracias.", "¡De una! Muchísimas gracias.", "Si no es molestia, sí. ¡Gracias!", "Ay, sí, dale. ¡Te agradezco un montón!", "Bueno, si no te molesta. ¡Gracias!", "¡Sí! Me salvás. Gracias.", "¿En serio? ¡Sí, gracias! Es re pesado."] }, prep: { rechazar: ["e05"], aceptar: [] }, wrong: { aceptar: [{ said: ["no gracias", "no hace falta", "no te preocupes", "puedo yo", "lo subo yo", "no te hagas problema"], r: "r", es: ["Dale, dejame que te ayudo igual, que eso pesa un montón.", "Ay, no, que pesa. Te doy una mano igual, ¿dale?"] }], rechazar: [] } },
      { pick: "ayuda", r: "j", es: { rechazar: ["Bueno. Y acordate: mañana sin agua, eh.", "Dale. Y no te olvides de que mañana cortan el agua.", "Bueno, y acordate de lo del agua mañana, eh.", "Listo. Ojo mañana con el agua, que la cortan.", "Perfecto. Ah, y mañana llená unas botellas, que cortan el agua.", "Bueno, como quieras. Y acordate que mañana no hay agua.", "Joya. Y ojo, que mañana a la mañana no hay agua.", "Listo. Te recuerdo lo del agua para mañana, eh.", "Está bien. No te olvides, eh: mañana se corta el agua.", "Bárbaro. Y mañana guardate un poco de agua, que la cortan."], aceptar: ["Mejor, que pesa, eh. Y acordate: mañana sin agua.", "Bien, así es más fácil. Y no te olvides de que mañana cortan el agua.", "Buenísimo, que pesa bastante. Y acordate de lo del agua mañana, eh.", "Listo, mejor así. Ojo mañana con el agua, que la cortan.", "Mejor así, que pesa. Ah, y mañana llená unas botellas, que cortan el agua.", "Bueno, entre dos es más fácil. Y acordate que mañana no hay agua.", "Joya, así es más liviano. Y ojo, que mañana a la mañana no hay agua.", "Listo, mejor, que eso pesa. Te recuerdo lo del agua para mañana, eh.", "Qué bien, que pesa un montón. No te olvides, eh: mañana se corta el agua.", "Bárbaro, que eso pesa. Y mañana guardate un poco de agua, que la cortan."] } },
      { you: "Thank {j:Julia|Julio} for letting you know about the water.", ok: [["gracias"], ["agradezc"]], best: "Gracias por avisar, {j:Julia|Julio}.", alts: ["¡Gracias por el aviso!", "Sí, gracias, {j:Julia|Julio}. Hoy lleno unas botellas.", "Gracias, lo tengo en cuenta.", "Dale, ¡mil gracias por avisarme!", "Sí, sí, me acuerdo. ¡Gracias, {j:Julia|Julio}!", "Gracias, {j:Julia|Julio}. Me guardo agua por las dudas.", "Te agradezco el aviso.", "Gracias, che. Me baño esta noche, entonces.", "Ah, gracias, menos mal que me avisaste.", "Muchas gracias, {j:Julia|Julio}. ¡Sos un sol!"], prep: ["e06"] }
